import test from 'node:test';import assert from 'node:assert/strict';import {collect,queryParams} from './worker/api.mjs';
const url=new URL('https://example.test/api/parcels?city=Riverview&q=Causeway&kind=land');
test('Collector validates input and limits query',()=>{const p=queryParams(url);assert.equal(p.get('resultRecordCount'),'100');assert.match(p.get('where'),/BLDG = 0/);assert.throws(()=>queryParams(new URL("https://example.test/api/parcels?city=Riverview&q=' OR 1=1")));assert.throws(()=>queryParams(new URL('https://example.test/api/parcels?city=Wesley%20Chapel&q=Main')));});
test('Collector preserves land and mailing address without inventing signals',async()=>{const data=await collect(url,async()=>Response.json({features:[{attributes:{Acc_Folio:'123.0000',SITE_ADDR:'Test address',SITE_CITY:'Riverview',OWNER:'Fixture owner',ADDR_1:'PO Box 1',CITY:'Tampa',STATE:'FL',ZIP:'33601',BLDG:0,LAND:100}}],exceededTransferLimit:true}));assert.equal(data.rows[0].mailingaddress,'PO Box 1, Tampa, FL, 33601');assert.match(data.rows[0].notes,/building value: 0/);assert.equal(data.rows[0].probate,undefined);assert.equal(data.more,true);});
test('Upstream errors do not produce records',async()=>{await assert.rejects(collect(url,async()=>Response.json({error:{code:500}})));await assert.rejects(collect(url,async()=>new Response('Unavailable',{status:503})));});
test('Worker serves old modules and rejects invalid requests',async()=>{const worker=(await import('./worker/index.js')).default;assert.equal((await worker.fetch(new Request('https://example.test/'))).status,200);assert.match(await(await worker.fetch(new Request('https://example.test/app.mjs'))).text(),/baruch-ermi-leads-v1/);assert.equal((await worker.fetch(new Request('https://example.test/api/parcels?q=x'))).status,400);assert.equal((await worker.fetch(new Request('https://example.test/api/parcels',{method:'POST'}))).status,405);});
